cieIfContextName = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 276, 1, 1, 2, 1, 8), OctetString().subtype(subtypeSpec=ValueSizeConstraint(0, 32)).clone('')).setMaxAccess("readonly")
